import json
import os
from pathlib import Path
import tempfile


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def compare(expected, actual):
    differences = []
    if len(expected) != len(actual):
        differences.append(f"row count: expected {len(expected)}, got {len(actual)}")
    for i, (left, right) in enumerate(zip(expected, actual)):
        if left != right:
            differences.append(f"row {i}: expected {left!r}, got {right!r}")
    return differences


def record(path, rows):
    path = Path(path)
    with tempfile.NamedTemporaryFile(mode="w", dir=path.parent, encoding="utf-8",
                                     delete=False) as stream:
        temp = Path(stream.name)
        json.dump(rows, stream, indent=2)
        stream.write("\n")
    try:
        os.replace(temp, path)
    finally:
        temp.unlink(missing_ok=True)


def inspect_candidate(path, rows):
    return compare(read(path), rows)


def approval_view(path, rows):
    """Replay a receipted approval in its original case order and calendar edition.

    Receipt paths are relative to the receipt, not the process working directory.
    Unreceipted tables retain the ordinary positional, live-calendar behavior.
    """
    path = Path(path)
    receipt_path = path.parent / "receipt.json"
    if not receipt_path.exists():
        return rows, None
    receipt = read(receipt_path)
    base = receipt_path.parent
    if (base / receipt["table"]).resolve() != path.resolve():
        return rows, None

    order = read(base / receipt["case_order"])
    by_case = {}
    for row in rows:
        case = row.get("case")
        if not isinstance(case, str) or case in by_case:
            raise ValueError("approval input must have unique string case IDs")
        by_case[case] = row
    if (not isinstance(order, list)
            or any(not isinstance(case, str) for case in order)
            or len(set(order)) != len(order)):
        raise ValueError("approval order must contain unique string case IDs")
    if set(order) != set(by_case):
        raise ValueError("approval order and input case IDs do not match")
    return [by_case[case] for case in order], base / receipt["calendar_edition"]
